        if up == "TRUE" { return Expr::Bool(true); }
        if up == "FALSE" { return Expr::Bool(false); }
        self.i = st;
        if let Some(e) = self.refexpr(self.sheet) { return e; }
        self.i = st + id.len().max(1);
        Expr::Err(6)
    }
