    // convert R/A to scalar (implicit intersection)
    pub fn deref_scalar(&mut self, v: V) -> V {
        match v {
            V::R(sh, r1, c1, r2, c2) => {
                if r1 == r2 && c1 == c2 { return self.cell(sh, r1, c1); }
                let (_, cr, cc) = self.cur;
