                V::S(s) => out.push(parse_num_str(&s).ok_or(2u8)?),
                V::B(b) => out.push(if b { 1.0 } else { 0.0 }),
                V::N(x) => out.push(x),
                V::Empty => {}
            }
        }
        Ok(())
    }
    fn vals_flat(&mut self, e: &Expr) -> Vec<V> {
        let v = self.eval(e);
        match v {
            V::R(..) | V::A(_) => { let a = self.to_arr(v); a.d.clone() }
            x => vec![x],
        }
    }

    fn ifs_generic(&mut self, args: &[Expr], first: usize) -> Result<Vec<(u32, u32)>, u8> {
        // returns matching offsets (dr, dc) relative to first range
        let mut sets: Vec<((u16, u32, u32, u32, u32), Crit)> = Vec::new();
        let mut i = first;
